contracts/MockUSDT.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

contract MockUSDT {
    string public name = "Mock USDT";
    string public symbol = "USDT";
    uint8 public decimals = 18;
    uint256 public totalSupply = 1000000 * 10**18; // 1 Juta Mock USDT
    mapping(address => uint256) public balanceOf;
    mapping(address => mapping(address => uint256)) public allowance;

    constructor() {
        balanceOf[msg.sender] = totalSupply;
    }

    function transfer(address to, uint256 amount) public returns (bool) {
        require(balanceOf[msg.sender] >= amount, "Saldo tidak cukup");
        balanceOf[msg.sender] -= amount;
        balanceOf[to] += amount;
        return true;
    }

    function approve(address spender, uint256 amount) public returns (bool) {
        allowance[msg.sender][spender] = amount;
        return true;
    }

    function transferFrom(address from, address to, uint256 amount) public returns (bool) {
        require(balanceOf[from] >= amount, "Saldo tidak cukup");
        require(allowance[from][msg.sender] >= amount, "Belum di-approve");
        balanceOf[from] -= amount;
        balanceOf[to] += amount;
        allowance[from][msg.sender] -= amount;
        return true;
    }
}

contracts/SimpleSwap.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

// Interface standar ERC20 agar kontrak ini bisa berinteraksi dengan token
interface IERC20 {
    function transfer(address to, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
}

contract SimpleSwap {
    IERC20 public tokenZTX;
    IERC20 public tokenUSDT;
    
    // Nilai tukar tetap: 1 USDT = 10 ZTX (bisa Anda sesuaikan nanti)
    uint256 public rate = 10; 

    constructor(address _tokenZTX, address _tokenUSDT) {
        tokenZTX = IERC20(_tokenZTX);
        tokenUSDT = IERC20(_tokenUSDT);
    }

    // Fungsi utama untuk menukar USDT menjadi ZTX
    function swapUsdtForZtx(uint256 amountUSDT) public {
        uint256 amountZTX = amountUSDT * rate;
    require(tokenZTX.balanceOf(msg.sender) >= amountZTX, "Saldo ZTX tidak cukup");

    require(tokenUSDT.balanceOf(msg.sender) >= amountUSDT, "Saldo USDT tidak cukup");
        
        // Kirim ZTX dari contract ke user
    require(tokenZTX.transfer(msg.sender, amountZTX), "Transfer ZTX gagal");
    }
}

contracts/Test.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

contract Test {
    struct Quest { string title; uint256 reward; bool active; }

    address public owner;
    Quest[] public quests;
    mapping(address => uint256) public points;
    mapping(address => mapping(uint256 => bool)) public completed;

    event QuestAdded(uint256 indexed questId, string title);
    event QuestCompleted(address indexed player, uint256 indexed questId, uint256 reward);

    constructor() { owner = msg.sender; }

    function addQuest(string memory title, uint256 reward) public {
        require(msg.sender == owner, "only owner can add quests");
        quests.push(Quest(title, reward, true));
        emit QuestAdded(quests.length - 1, title);
    }

    function completeQuest(uint256 questId) public {
        require(questId < quests.length, "quest does not exist");
        require(quests[questId].active, "quest is not active");
        require(!completed[msg.sender][questId], "already completed");
        completed[msg.sender][questId] = true;
        points[msg.sender] += quests[questId].reward;
        emit QuestCompleted(msg.sender, questId, quests[questId].reward);
    }

    function questCount() public view returns (uint256) {
        return quests.length;
    }
}

